            foreground = [x for row in pattern for x in row if x != 0]
            color = max(set(foreground), key=foreground.count) if foreground else 0
            out = [[2 if x == color else x for x in row] for row in pattern]
            for i in range(min(len(out), len(mask))):
                for j in range(min(w, len(mask[i]))):
                    if mask[i][j] == 0 and pattern[i][j] == color:
